    static constexpr int NUM_CONSUMER_WARPS = 12, NUM_WORKERS = 3;
    static constexpr int INPUT_PIPE_STAGES = 2;

    // Producer (load worker, warp_id==0):
    static void load(producer_load_args) {
        if(warpgroup::warpid() == 0) {
            tma::expect(inputs_arrived, block.k, block.v);
            tma::load_async(block.k, globals.K, {batch, head, iter, 0}, inputs_arrived);
            tma::load_async(block.v, globals.V, {batch, head, iter, 0}, inputs_arrived);
        }
        else arrive(inputs_arrived);
    }
    // Consumer (compute warpgroups, NUM_WORKERS=3):
    static void compute(consumer_compute_args) {
        warpgroup::mm_ABt(att, scratch.q[state.id], block.k); // Q@K^T
        warpgroup::mma_async_wait();
        sub_row(att, att, max_vec);   // softmax
        exp(att, att);
        div_row(att, att, norm_vec);
        copy(att_bf16, att);          // fp32→bf16
        warpgroup::mma_AB(state.o, att_bf16, block.v); // att@V
        warpgroup::mma_async_wait();
        arrive(inputs_finished);
    }
    // Store worker (same warp as producer):
    static void store(producer_store_args) { ... tma::store_async ... }
    // Finish: final normalization + writeback
    static void finish(consumer_finish_args) { div_row + tma::store_async to HBM }
};
```
关键调度特征：
- Load worker (warp 0) 使用 TMA 异步加载 K/V tiles 到 2-stage pipeline buffer (INPUT_PIPE_STAGES=2)
- Compute workers (3 个 warpgroups) 在 register 中执行 mma+softmax+mfma
- 当 compute 执行时 load worker 预取下一个 tile（隐藏 HBM 延迟）
- 当 compute 通过 arrive(inputs_finished) 通知后，load worker 可覆盖已消费的 buffer slot

